import re


INVALID_FREQ = -47


class Match(object):
    def __bool__(self):
        raise NotImplementedError


class GnbMatch(Match):
    GNB_MATCHER = '.* set_gnb.* id=([0-9]+).*'

    def __init__(self, line):
        self._result = re.match(self.GNB_MATCHER, line)

    def gnb_identifier(self):
        return self._result.group(1)

    def __bool__(self):
        return bool(self._result)


class CellMatch(Match):
    ID_MATCHER = '.* set_cell.* id=([0-9]+).*'
    GNB_MATCHER = '.* set_cell.* gnb=([0-9]+).*'
    NRARFCN_MATCHER = '.* set_cell.* nr_arfcn=[0-9]+:([0-9]+).*'

    def __init__(self, line):
        self._id = re.match(self.ID_MATCHER, line)
        self._gnb = re.match(self.GNB_MATCHER, line)
        self._nrarfcn = re.match(self.NRARFCN_MATCHER, line)

    def cell_identifier(self):
        return self._id.group(1)

    def gnb_identifier(self):
        return self._gnb.group(1)

    def nrarfcn(self):
        try:
            return int(self._nrarfcn.group(1))
        except AttributeError:
            return INVALID_FREQ

    def __bool__(self):
        return bool(self._id) and bool(self._gnb)


class IDMapper:
    def __init__(self, filepath):
        self._filepath = filepath
        self._data = []

        with open(self._filepath) as f:
            self._data = f.readlines()

    @staticmethod
    def _filter_commands(command, lines):
        return [line for line in lines if command in line]

    def prepare_mapping(self):
        mapping = {}
        for cmd in IDMapper._filter_commands('set_gnb', self._data):
            gnb_match = GnbMatch(cmd)

            if gnb_match:
                mapping[gnb_match.gnb_identifier()] = []

        for cmd in IDMapper._filter_commands('set_cell', self._data):
            cell_match = CellMatch(cmd)

            if cell_match and self._identifier_could_be_appended(cell_match, mapping):
                mapping[cell_match.gnb_identifier()].append(cell_match.cell_identifier())
        return mapping

    def _identifier_could_be_appended(self, cell_match, mapping):
        return cell_match.gnb_identifier() in mapping


class OnlyExpectedFreqsIDMapper(IDMapper):
    def __init__(self, filepath, expected_frequencies):
        super(OnlyExpectedFreqsIDMapper, self).__init__(filepath)
        self._expected_frequencies = expected_frequencies

    def _identifier_could_be_appended(self, cell_match, mapping):
        return cell_match.gnb_identifier() in mapping and cell_match.nrarfcn() in self._expected_frequencies
